-- 绑定一个 inspectHint 到一个 inspect ui面板



---@class BindInspectHint
---@field inspectHintBehaviour     Engine.Modules.LuaBehaviour
local BindInspectHint = Class('BindInspectHint')
-- 外部调用时使用:
-- local BindInspectHint = import('Game.DreamSpace.Level1.BindInspectHint')


-- ========================================================



--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

local InspectHint = import('Game.DreamSpace.Hint.InspectHint')

local DreamSpaceLuaUtils = import('Game.DreamSpace.Tools.DreamSpaceLuaUtils')

---@type DreamSpaceStates
local DreamSpaceStates = import('Game.DreamSpace.Tools.DreamSpaceStates')
local OpenState = DreamSpaceStates.OpenState

local UI_Inspect = import('Game.DreamSpace.Level1.UI.UI_Inspect')

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local Vector3 = CS.UnityEngine.Vector3

local DreamSpaceUtils = CS.DreamSpace.DreamSpaceUtils

local Interrupter = CS.ElectricalSystem.ElectricalSwitch.Interrupter
local LuaBehaviour = CS.Engine.Modules.LuaBehaviour


-- ========================================================



-- ========================================================



function BindInspectHint:__init()
    self.controller = nil

    self.DoBeforeTriggerInterrupter = nil -- 协程函数指针, 比如 "开关被开启" 动画的完整播放
end


function BindInspectHint:__delete()
    self.co_1 = nil
    self.co_2 = nil
end



function BindInspectHint:Awake()
    KTool.SetActive(self.controller.gameObject, true)
end

function BindInspectHint:Start()
    KTool.SetActive(self.controller.gameObject, true)

    assert( self.inspectHintBehaviour )


    self.inspectHint = DreamSpaceLuaUtils.GetLuaScr(self.inspectHintBehaviour.gameObject, "Game.DreamSpace.Hint.InspectHint" )
    assert( isNotNull(self.inspectHint) )

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = cs_coroutine.start(self.DelayInit, self)
end




function BindInspectHint:DelayInit() 

    coroutine.yield(Yielders.EndOfFrame)

    -- -- 只尝试有限次;
    for i=1,DreamSpaceStates.DelayInitWaitFrames do
        if self.inspectHint.isInit == true then
            self.inspectHint:BindHintButton( Bind(self,self.WhenPressButton) )
            return
        end 
        coroutine.yield(Yielders.EndOfFrame)
    end 
    printError( "始终没等到 inspectHint 初始化完成, 请查看 inspectHint 是否存在异常" )
end


function BindInspectHint:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co )
    self.co = nil 
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


-- -- ===============================================================


function BindInspectHint:WhenPressButton() 

    local ui_Inspect = UI_Inspect.Instance()
    if isNotNull(ui_Inspect) then
        if ui_Inspect:GetOpenState() == OpenState.Closed then

            DreamSpaceLuaUtils.StopCoroutine( self.co )
            self.co = cs_coroutine.start(function()
                
                -- todo: 搞到 文本

                ui_Inspect:Show( "AAA", "BBBBBBB" )

                self.inspectHint:Hide() -- 隐藏 inspectHint 按钮
                -- 一直等到 inspect 窗口消失:
                coroutine.yield(Yielders.EndOfFrame)
                while isNotNull(ui_Inspect) and ui_Inspect:GetOpenState() ~= OpenState.Closed do 
                    coroutine.yield(Yielders.EndOfFrame)
                end 
                self.inspectHint:Show() -- 恢复显示 inspectHint 按钮


            end) 
        end
    end

end






return BindInspectHint
